  "id" uuid PRIMARY KEY,
  "schedule" TEXT NOT NULL,
  "tick_at" TIMESTAMPTZ NOT NULL,
  "late" boolean NOT NULL,
  "caller" TEXT,
  "txid" BIGINT DEFAULT pg_current_xact_id()::text::bigint
);

